void nodeRename(Proxy &node, const RegexMatchConfigs &rename_array, extra_settings &ext)
{
    std::string &remark = node.Remark, original_remark = node.Remark, returned_remark, real_rule;

    for(const RegexMatchConfig &x : rename_array)
    {
        if(!x.Script.empty())
        {
            script_safe_runner(ext.js_runtime, ext.js_context, [&](qjs::Context &ctx)
            {
                std::string script = x.Script;
                if(startsWith(script, "path:"))
                    script = fileGet(script.substr(5), true);
                try
                {
                    ctx.eval(script);
                    auto rename = (std::function<std::string(const Proxy&)>) ctx.eval("rename");
                    returned_remark = rename(node);
                    if(!returned_remark.empty())
                        remark = returned_remark;
                }
                catch (qjs::exception)
                {
                    script_print_stack(ctx);
                }
            }, global.scriptCleanContext);
            continue;
        }
        if(applyMatcher(x.Match, real_rule, node) && real_rule.size())
            remark = regReplace(remark, real_rule, x.Replace);
    }
    if(remark.empty())
        remark = original_remark;
    return;
}

int DecodeSCA(Eventinfo *lf, int *socket)
{
    assert(lf);

    int ret_val = 1;
    cJSON *json_event = NULL;
    cJSON *type = NULL;
    lf->decoder_info = sca_json_dec;
    const char *jsonErrPtr;

    if (json_event = cJSON_ParseWithOpts(lf->log, &jsonErrPtr, 0), !json_event)
    {
        merror("Malformed configuration assessment JSON event.");
        return ret_val;
    }

    assert(json_event);

    /* TODO - Check if the event is a final event */
    type = cJSON_GetObjectItem(json_event, "type");

    if(type) {

        if (strcmp(type->valuestring,"check") == 0){
            char *msg_unformatted = cJSON_PrintUnformatted(json_event);

            if (msg_unformatted) {
                mdebug1("Got check event: '%s'", msg_unformatted);
                os_free(msg_unformatted);
            }

            HandleCheckEvent(lf,socket,json_event);

            lf->decoder_info = sca_json_dec;

            cJSON_Delete(json_event);
            ret_val = 1;
            return ret_val;
        }
        else if (strcmp(type->valuestring,"summary") == 0){
            char *msg_unformatted = cJSON_PrintUnformatted(json_event);

            if (msg_unformatted) {
                mdebug1("Got summary event: '%s'", msg_unformatted);
                os_free(msg_unformatted);
            }

            HandleScanInfo(lf,socket,json_event);
            lf->decoder_info = sca_json_dec;

            cJSON_Delete(json_event);
            ret_val = 1;
            return ret_val;
        } else if (strcmp(type->valuestring,"policies") == 0){
            char *msg_unformatted = cJSON_PrintUnformatted(json_event);

            if (msg_unformatted) {
                mdebug1("Got policies event: '%s'", msg_unformatted);
                os_free(msg_unformatted);
            }

            HandlePoliciesInfo(lf,socket,json_event);

            lf->decoder_info = sca_json_dec;

            cJSON_Delete(json_event);
            ret_val = 1;
            return ret_val;
        } else if (strcmp(type->valuestring,"dump_end") == 0) {
            char *msg_unformatted = cJSON_PrintUnformatted(json_event);

            if (msg_unformatted) {
                mdebug1("Got dump finished event: '%s'", msg_unformatted);
                os_free(msg_unformatted);
            }

            HandleDumpEvent(lf,socket,json_event);
            lf->decoder_info = sca_json_dec;

            cJSON_Delete(json_event);
            ret_val = 1;
            return ret_val;
        }
    } else {
        ret_val = 0;
        goto end;
    }

    ret_val = 1;

end:
    cJSON_Delete(json_event);
    return (ret_val);
}

